   n=wn(l,pnames[j]); fp=np.load(f'factor/{l}_{j}.npz');B=fp['B'];Q=qa(l,j); A=Q+z*fp['Z']; H=hres(l,j); scl=a
   if j==3:scl*=orate
   if H is not None and protect>=0 and mode=='orth':
    A=A-rkey(A,H[120:220],protect)
